import { Notice, Plugin } from "obsidian";

export default class HelloPlugin extends Plugin {
  async onload() {
    console.log("Hello plugin loaded");

    this.addCommand({
      id: "say-hello",
      name: "Say hello",
      callback: () => {
        new Notice("Hello from my plugin!");
      },
    });
  }

  onunload() {
    console.log("Hello plugin unloaded");
  }
}
